  #search-box { width: 300px; padding: 6px; }
  #results { position: absolute; background: white; border: 1px solid #ccc; max-height: 200px; overflow-y: auto; width: 300px; }
  .result { padding: 4px 8px; cursor: pointer; }
  .result:hover { background: #f0f0f0; }
</style>

<input id="search-box" placeholder="Search OSM…" />
<div id="results"></div>
<div id="map" style="width:100%;height:400px;"></div>

